{
  "units": [
    {
      "quote_ref": "F001",
      "scope_refs": [],
      "kind": "background",
      "meaning": "Section heading for 29 CFR 1910.132 establishing the subject as general requirements, serving as an organizational title without independent substantive obligations."
    },
    {
      "quote_ref": "F002",
      "scope_refs": [],
      "kind": "requirement",
      "meaning": "Protective equipment—including personal protective equipment for eyes, face, head, and extremities, protective clothing, respiratory devices, and protective shields and barriers—shall be provided, used, and maintained in a sanitary and reliable condition wherever necessary due to hazards of processes or environment, chemical hazards, radiological hazards, or mechanical irritants encountered in a manner capable of causing injury or impairment in the function of any part of the body through absorption, inhalation, or physical contact."
    },
    {
      "quote_ref": "F003",
      "scope_refs": [],
      "kind": "requirement",
      "meaning": "Where employees provide their own protective equipment, the employer shall be responsible for assuring its adequacy, including proper maintenance and sanitation of such equipment."
    },
    {
      "quote_ref": "F004",
      "scope_refs": [],
      "kind": "requirement",
      "meaning": "All personal protective equipment shall be of safe design and construction for the work to be performed."
    },
    {
      "quote_ref": "F005",
      "scope_refs": [],
      "kind": "requirement",
      "meaning": "The employer shall assess the workplace to determine if hazards are present, or are likely to be present, which necessitate the use of personal protective equipment (PPE)."
    },
    {
      "quote_ref": "F006",
      "scope_refs": [
        "F005"
      ],
      "kind": "requirement",
      "meaning": "If hazards necessitating the use of PPE are present or likely to be present, the employer shall select, and have each affected employee use, the types of PPE that will protect the affected employee from the hazards identified in the hazard assessment."
    },
    {
      "quote_ref": "F007",
      "scope_refs": [
        "F005"
      ],
      "kind": "requirement",
      "meaning": "If hazards necessitating the use of PPE are present or likely to be present, the employer shall communicate selection decisions to each affected employee."
    },
    {
      "quote_ref": "F008",
      "scope_refs": [
        "F005"
      ],
      "kind": "requirement",
      "meaning": "If hazards necessitating the use of PPE are present or likely to be present, the employer shall select PPE that properly fits each affected employee."
    },
    {
      "quote_ref": "F009:F010",
      "scope_refs": [],
      "kind": "statement",
      "meaning": "Non-mandatory Appendix B contains an example of procedures that would comply with the requirement for conducting a hazard assessment."
    },
    {
      "quote_ref": "F011",
      "scope_refs": [],
      "kind": "requirement",
      "meaning": "The employer shall verify that the required workplace hazard assessment has been performed through a written certification that identifies the workplace evaluated, the person certifying that the evaluation has been performed, the date(s) of the hazard assessment, and which identifies the document as a certification of hazard assessment."
    },
    {
      "quote_ref": "F012",
      "scope_refs": [],
      "kind": "prohibition",
      "meaning": "Defective or damaged personal protective equipment shall not be used."
    },
    {
      "quote_ref": "F013",
      "scope_refs": [],
      "kind": "requirement",
      "meaning": "The employer shall provide training to each employee who is required by this section to use PPE, ensuring each such employee is trained to know at least the specified training subjects."
    },
    {
      "quote_ref": "F014",
      "scope_refs": [
        "F013"
      ],
      "kind": "requirement",
      "meaning": "For each employee required by this section to use PPE, the required training shall at least ensure the employee knows when PPE is necessary."
    },
    {
      "quote_ref": "F015",
      "scope_refs": [
        "F013"
      ],
      "kind": "requirement",
      "meaning": "For each employee required by this section to use PPE, the required training shall at least ensure the employee knows what PPE is necessary."
    },
    {
      "quote_ref": "F016",
      "scope_refs": [
        "F013"
      ],
      "kind": "requirement",
      "meaning": "For each employee required by this section to use PPE, the required training shall at least ensure the employee knows how to properly don, doff, adjust, and wear PPE."
    },
    {
      "quote_ref": "F017",
      "scope_refs": [
        "F013"
      ],
      "kind": "requirement",
      "meaning": "For each employee required by this section to use PPE, the required training shall at least ensure the employee knows the limitations of the PPE."
    }
  ]
}
